using System;

class Program
{
    static void Main(string[] args)
    {
        int[] array = { 12, 5, 9, 24, 15, 3 };
        int[] sortedArray = MergeSortDescending(array);

        Console.WriteLine("Sorted array:");
        foreach (int num in sortedArray)
        {
            Console.WriteLine(num);
        }
    }

    static int[] MergeSortDescending(int[] array)
    {
        if (array.Length <= 1)
        {
            return array;
        }

        int mid = array.Length / 2;
        int[] left = new int[mid];
        int[] right = new int[array.Length - mid];

        Array.Copy(array, 0, left, 0, mid);
        Array.Copy(array, mid, right, 0, array.Length - mid);

        left = MergeSortDescending(left);
        right = MergeSortDescending(right);

        return MergeDescending(left, right);
    }

    static int[] MergeDescending(int[] left, int[] right)
    {
        int leftIndex = 0;
        int rightIndex = 0;
        int resultIndex = 0;
        int[] result = new int[left.Length + right.Length];

        while (leftIndex < left.Length && rightIndex < right.Length)
        {
            if (left[leftIndex] >= right[rightIndex])
            {
                result[resultIndex] = left[leftIndex];
                leftIndex++;
            }
            else
            {
                result[resultIndex] = right[rightIndex];
                rightIndex++;
            }
            resultIndex++;
        }

        while (leftIndex < left.Length)
        {
            result[resultIndex] = left[leftIndex];
            leftIndex++;
            resultIndex++;
        }

        while (rightIndex < right.Length)
        {
            result[resultIndex] = right[rightIndex];
            rightIndex++;
            resultIndex++;
        }

        return result;
    }
}
